__NUXT_JSONP__("/svet/stat/surinam/ceny", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{tabsLoad:{tabWhatToSee:d,tabPrice:d,tabPeople:d,tabTrip:d,tabContact:d,tabHotel:d,tabNeighboring:i,tabVideos:f,tabArticles:f,tabWallSockets:g,tabChains:i,tabFauna:f,tabFlora:f,tabFoods:f,tabBrands:f},place:[{tld:".sr",name:"Surinam",area:163820,population:591919,slug:k,id_continent:g,information_chatgpt:"\u003Cp\u003ESurinam, také nazývaný Surinamská republika, je malá země v Jižní Americe. Sousedí s Brazílií, Guyanou a Francouzskou Guyanou. Surinam má rozlohu 163 820 km² a žije zde přibližně 600 000 lidí. Oficiálním jazykem je nizozemština, ale většina obyvatel hovoří také surinamskou kreolštinou.\u003C\u002Fp\u003E\n\u003Cp\u003ESurinam je velmi rozmanitý zeměpisně i kulturně. Nachází se zde tropický deštný prales, říční pláně a pobřeží Atlantského oceánu. V Surinamu žije mnoho etnických skupin, včetně kreolů, Javanů, Indů a mnoha dalších.\u003C\u002Fp\u003E\n\u003Cp\u003ESurinam má bohatou historii, kterou ovlivnili kolonizátoři z Nizozemska, Anglie a Francie. Země získala nezávislost v roce 1975 a od té doby se snaží vyrovnat s mnoha výzvami, jako je například ochrana životního prostředí a boj proti chudobě.\u003C\u002Fp\u003E\n\u003Cp\u003EPro turisty nabízí Surinam mnoho přírodních krás a kulturních zážitků. Největším městem je Paramaribo, které je zapsáno na seznamu světového dědictví UNESCO. Dalšími atrakcemi jsou například vodopády Raleigh Falls a vodopády Blanche Marie, Národní park Central Suriname Nature Reserve nebo návštěva plantáží, kde se pěstuje káva a kakao.\u003C\u002Fp\u003E \n\u003Cp\u003ESurinam je také známý pro svoji kuchyni, která kombinuje vlivy evropské, africké, indické a jihovýchodní asijské kuchyně. Mezi místní speciality patří například pom, kréolská polévka z kořenové zeleniny a masa, nebo roti, placka z kukuřičné mouky, která se podává s kořenovou zeleninou a omáčkou z luskovin.\u003C\u002Fp\u003E",money_prices:[{name:"Taxi (cena za km)",value:3.5,date_update:b},{name:"Hlavní jídlo",value:35,date_update:b},{name:"Chleba",value:2.5,date_update:b},{name:"Mléko",value:6.5,date_update:b},{name:"Voda (500ml)",value:i,date_update:b},{name:"Espresso",value:7.5,date_update:b},{name:"Zmrzlina (jeden kopeček)",value:l,date_update:b},{name:"Pivo",value:l,date_update:b},{name:"Krabička cigaret",value:30,date_update:b},{name:"Big Mac",value:25,date_update:b},{name:"Coca Cola (500ml)",value:5,date_update:b}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:m,date_update:c},{name:"Policie",value:m,date_update:c},{name:"Hasiči",value:"110",date_update:c},{name:"Zdravotnická záchranná služba",value:"114",date_update:c}],phone_prefix:"+597",coordinates:[{latitude:"3.9193",longitude:"-56.0278"}],people_religion:[{name:"Křesťanství",value:"49%",date_update:h},{name:"Hinduismus",value:"22%",date_update:h},{name:"Islam",value:"14%",date_update:h},{name:"Jiná náboženství",value:n,date_update:h},{name:"Bez vyznání",value:"5%",date_update:h}],people_nationality:[{name:"Creole",value:"37%",date_update:e},{name:"Hindustani",value:"27%",date_update:e},{name:"Javanese",value:"15%",date_update:e},{name:"Maroon",value:n,date_update:e},{name:"Amerindian",value:"3%",date_update:e},{name:"Chinese",value:"1%",date_update:e},{name:"Other",value:"7%",date_update:e}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Surinamu je pro občana České republiky vyžadován cestovní pas, občanský průkaz nestačí.",date_update:c},{name:"Cestovní pas",value:"Pro vstup do Surinamu je pro občana České republiky nezbytný platný cestovní pas.",date_update:c},{name:"Vízum",value:"Pro vstup do Surinamu je pro občana České republiky vyžadováno vízum, které lze získat na ambasádě Surinamu v Německu. Vízum se vydává na 90 dní a lze ho prodloužit. Informace o aktuálních podmínkách získáte na ambasádě Surinamu.",date_update:c},{name:"Očkování",value:"Před cestou do Surinamu jsou doporučována očkování proti žluté zimnici, hepatitidě A a B a břišnímu tyfu. Další informace o očkování získáte na webu cestovní medicíny nebo u odborníka na cestování.",date_update:c},{name:"Cestovní pojištění",value:"Pro vstup do Surinamu není vyžadováno cestovní ani zdravotní pojištění, ale je doporučeno si je sjednat kvůli případnému onemocnění či úrazu.",date_update:c},{name:"Bezpečnostní situace",value:"Surinam je obecně bezpečná země, ale v některých oblastech může být vysoká kriminalita. Je třeba být obezřetný a vyhýbat se osamělým a temným ulicím a místům. Doporučuje se být opatrný zejména v noci. Informace o aktuální bezpečnostní situaci získáte na webu Ministerstva zahraničních věcí ČR nebo u cestovní kanceláře.",date_update:c},{name:"Další informace",value:"V Surinamu se mluví nizozemsky, anglicky a surinamskou kreolštinou. Většina obyvatelstva je křesťanského vyznání. Klima je tropické s vysokou vlhkostí. Platí zde levý provoz na silnicích. Místní měnou je surinamský dolar. Další informace o zvyklostech, kultuře a podobně získáte na webu Ministerstva zahraničních věcí ČR nebo u cestovní kanceláře.",date_update:c}],type_place:o,id_image_cover:j,id_image_hero:j,id_city_main:2043,affiliate:[{name:"booking",value:d}],mpz:"SR",alerts:a,zoom:[{google:6,booking:7}],ids_neighboring_countries:[{id:31},{id:80},{id:94}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:207,facts_place:a,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2024-03-04T19:48:12.84066+00:00",name_original:a,currency:[{code:"SRD",name:"Surinamský dolar"}],setting_top:d,setting_status_public:p}],imagePlace:[{id:j,name:k,source:"\u002Fworld\u002Fstates\u002F",type:o,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:g,slug:"jizni-amerika",name:"Jižní Amerika",area:17840000,population:430000000,population_density:24.11,number_states:12,information_chatgpt:"\u003Cp\u003EJižní Amerika je kontinent nacházející se v jižní polovině zeměkoule. Je druhým největším kontinentem v Americe a čtvrtým největším kontinentem na světě. Rozprostírá se od Karibiku na severu po Průliv Drakea na jihu, což představuje přibližně 7 000 kilometrů. Tento kontinent obývá více než 420 milionů lidí a skládá se ze 12 různých států.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má velmi rozmanitou geografii. Na západní straně kontinentu se nachází Andské pohoří, které je nejdelší pohoří na světě a táhne se přes 7 zemí. Na východní straně se nachází rozsáhlé deštné pralesy a oblasti savan. Kromě toho se zde nachází také největší řeka na světě - Amazonka, která má neuvěřitelný vliv na floru a faunu regionu.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také velmi bohatou historii a kulturu. Před příchodem Evropanů byla tato oblast domovem mnoha starověkých civilizací, jako jsou Inkové, Mayové a Aztékové. Tyto civilizace zanechaly pozoruhodné památky, jako jsou Machu Picchu, Chichén Itzá a Tiahuanaco. Později byla tato oblast ovlivněna kolonizací ze strany Španělska a Portugalska, což má dodnes vliv na jazyky, kulturu a způsob života.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika je také velmi oblíbenou turistickou destinací. V Argentině a Brazílii se nacházejí největší vodopády světa - Iguazú a Niagarské vodopády. Peru je domovem Machu Picchu, jedné z nejnavštěvovanějších archeologických lokalit na světě. Kromě toho jsou zde také krásné pláže, horské túry, národní parky a další přírodní krásy.\u003C\u002Fp\u003E\n\u003Cp\u003EV Jižní Americe se také nachází mnoho kulturních festivalů a událostí. Například karnevaly v Rio de Janeiru a Buenos Aires jsou světoznámé pro svou atmosféru a pestrost barev. Také zde můžete ochutnat mnoho unikátních kulinářských specialit, jako jsou arepas v Kolumbii, ceviche v Peru a asado v Argentině.\u003C\u002Fp\u003E\n\u003Cp\u003EZkrátka, Jižní Amerika je kontinent plnýkrás, kulturního bohatství a přírodních divů. Mnoho turistů sem přijíždí za poznáním exotického prostředí, ale také kvůli možnostem dobrodružství a sportovních aktivit. Například v Brazílii je oblíbená plážová fotbalová hra zvaná futevôlei, zatímco v Chile si turisté užívají snowboardování na Andách.\u003C\u002Fp\u003E\n\u003Cp\u003EJižní Amerika má také své problémy, jako je sociální nerovnost, kriminalita a korupce. Některé oblasti jsou považovány za nebezpečné pro turisty, takže je třeba být obezřetní a využívat služby kvalitních turistických průvodců.\u003C\u002Fp\u003E\n\u003Cp\u003EZávěrem lze říci, že Jižní Amerika je fascinující kontinent, který nabízí mnoho příležitostí pro poznání, zážitky a dobrodružství. Bez ohledu na to, jestli plánujete návštěvu kvůli přírodě, kultuře nebo jen na odpočinek na pláži, určitě nebudete zklamáni.\u003C\u002Fp\u003E",coordinates:[{latitude:-14.235004,longitude:-51.92528}],type_place:"continent",id_image_cover:g,id_image_hero:g,zoom:[{google:g,booking:i}],information_author:a,seo_tags:a,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2024-03-04T19:48:06.634661+00:00",name_original:a,setting_top:d,setting_status_public:p}]}],fetch:{},mutations:[]}}(null,"05-2021","05-2023",true,"04-2022",0,2,"2021",3,368,"surinam",10,"115","10%","state",1)));